// Package gen synthesises reproducible PostgreSQL log corpora.
//
// TST-001 through TST-003: a corpus is generated from a seed rather than
// committed, described by a manifest, and regenerated by "make corpus". That is
// not only about repository size. A generated corpus can be regenerated at any
// scale, contains no real data to scrub (COM-002), and -- the part that matters
// for the comparison -- has a KNOWN event stream, so the counts pgbadger,
// pgweasel and pglogwatch each report can be checked against the truth rather
// than only against each other (AC-010, COR-003).
//
// The same logical events are emitted in stderr, csvlog and jsonlog form
// (TST-002), which is what makes the differential comparison meaningful: any
// difference between the three outputs is the parser's, not the corpus's.
package gen

import (
	"fmt"
	"io"
	"math/rand/v2"
	"strings"
	"time"
)

// Event is one logical log event, independent of destination.
//
// The generator produces these once and renders each into three formats, which
// is what guarantees the three files describe identical activity.
type Event struct {
	Time       time.Time
	Severity   string
	SQLState   string
	User       string
	Database   string
	App        string
	Host       string
	Port       int
	PID        int32
	SessionID  string
	LineNum    int64
	CommandTag string
	VXID       string
	TXID       int64
	Message    string
	Detail     string
	Hint       string
	Statement  string
	Backend    string
	QueryID    int64
	Duration   time.Duration
}

// Mix is how many of each kind of event a corpus contains, as relative weights.
//
// The default reflects a busy application server: mostly slow-query logging,
// with errors and connections a small fraction and background activity rarer
// still. A corpus of nothing but errors would benchmark the error path rather
// than the parser.
type Mix struct {
	SlowQuery  int
	Connection int
	Error      int
	Autovacuum int
	Checkpoint int
	TempFile   int
	Deadlock   int
	LockWait   int
}

// DefaultMix is the weighting used by "make corpus".
var DefaultMix = Mix{
	SlowQuery:  60,
	Connection: 15,
	Error:      12,
	Autovacuum: 5,
	Checkpoint: 3,
	TempFile:   3,
	LockWait:   1,
	Deadlock:   1,
}

// Config controls generation.
type Config struct {
	Seed    uint64
	Records int
	Start   time.Time
	Mix     Mix
}

func (c *Config) normalize() {
	if c.Records <= 0 {
		c.Records = 1000
	}
	if c.Start.IsZero() {
		c.Start = time.Date(2026, 8, 30, 9, 0, 0, 0, time.UTC)
	}
	if c.Mix == (Mix{}) {
		c.Mix = DefaultMix
	}
}

// Generate produces the event stream for a configuration.
//
// It is deterministic: the same seed and record count always produce the same
// events, which is what TST-003 requires and what lets a published benchmark
// figure be reproduced (GUD-006).
func Generate(cfg Config) []Event {
	cfg.normalize()
	r := rand.New(rand.NewPCG(cfg.Seed, cfg.Seed^0x9E3779B97F4A7C15))

	weights, kinds := flattenMix(cfg.Mix)
	total := 0
	for _, w := range weights {
		total += w
	}

	events := make([]Event, 0, cfg.Records)
	now := cfg.Start
	var lineNum int64

	for i := range cfg.Records {
		// Time advances by a small random amount, so timestamps are
		// monotonic and unevenly spaced -- which is what a real log
		// looks like, and what makes the peaks report meaningful.
		now = now.Add(time.Duration(r.IntN(200)+1) * time.Millisecond)
		lineNum++

		pick := r.IntN(total)
		kind := kinds[0]
		for j, w := range weights {
			if pick < w {
				kind = kinds[j]
				break
			}
			pick -= w
		}
		events = append(events, makeEvent(r, kind, now, lineNum, i))
	}
	return events
}

type eventKind int

const (
	kindSlowQuery eventKind = iota
	kindConnection
	kindError
	kindAutovacuum
	kindCheckpoint
	kindTempFile
	kindLockWait
	kindDeadlock
)

func flattenMix(m Mix) ([]int, []eventKind) {
	return []int{
			m.SlowQuery, m.Connection, m.Error, m.Autovacuum,
			m.Checkpoint, m.TempFile, m.LockWait, m.Deadlock,
		}, []eventKind{
			kindSlowQuery, kindConnection, kindError, kindAutovacuum,
			kindCheckpoint, kindTempFile, kindLockWait, kindDeadlock,
		}
}

var (
	users     = []string{"app_user", "reporting", "etl", "admin", "grafana"}
	databases = []string{"appdb", "warehouse", "metrics"}
	apps      = []string{"psql", "pgbouncer", "myapp", "dbeaver", ""}
	tables    = []string{"orders", "customers", "line_items", "invoices", "sessions"}
)

func makeEvent(r *rand.Rand, k eventKind, now time.Time, lineNum int64, i int) Event {
	pid := int32(20000 + r.IntN(4000)) //nolint:gosec // synthetic data
	e := Event{
		Time:      now,
		Severity:  "LOG",
		SQLState:  "00000",
		User:      users[r.IntN(len(users))],
		Database:  databases[r.IntN(len(databases))],
		App:       apps[r.IntN(len(apps))],
		Host:      fmt.Sprintf("10.0.%d.%d", r.IntN(8), r.IntN(250)+1),
		Port:      32768 + r.IntN(20000),
		PID:       pid,
		SessionID: fmt.Sprintf("%08x.%x", now.Unix(), pid),
		LineNum:   lineNum,
		VXID:      fmt.Sprintf("%d/%d", r.IntN(20)+1, r.IntN(100000)),
		Backend:   "client backend",
	}
	table := tables[r.IntN(len(tables))]

	switch k {
	case kindSlowQuery:
		ms := float64(r.IntN(5000)) + r.Float64()
		e.Duration = time.Duration(ms * float64(time.Millisecond))
		e.CommandTag = "SELECT"
		e.QueryID = int64(r.Uint64() >> 1) //nolint:gosec // synthetic data
		e.Message = fmt.Sprintf(
			"duration: %.3f ms  statement: SELECT id, total FROM %s WHERE created_at > '2026-08-%02d' ORDER BY id LIMIT %d",
			ms, table, r.IntN(28)+1, r.IntN(1000)+1)

	case kindConnection:
		e.Message = fmt.Sprintf("connection authorized: user=%s database=%s application_name=%s",
			e.User, e.Database, e.App)

	case kindError:
		e.Severity = "ERROR"
		e.SQLState = "42P01"
		e.CommandTag = "SELECT"
		e.Message = fmt.Sprintf(`relation "%s_%d" does not exist at character 15`, table, i%97)
		e.Statement = fmt.Sprintf("SELECT * FROM %s_%d WHERE id = %d", table, i%97, r.IntN(100000))
		e.Detail = ""
		if r.IntN(3) == 0 {
			e.Severity = "ERROR"
			e.SQLState = "23505"
			e.Message = fmt.Sprintf(`duplicate key value violates unique constraint "%s_pkey"`, table)
			e.Detail = fmt.Sprintf("Key (id)=(%d) already exists.", r.IntN(1000000))
			e.Hint = "Use ON CONFLICT to ignore the duplicate."
			e.Statement = fmt.Sprintf("INSERT INTO %s (id) VALUES (%d)", table, r.IntN(1000000))
		}

	case kindAutovacuum:
		e.Backend = "autovacuum worker"
		// An autovacuum worker has a database but no user, application or
		// client -- which is what makes it exercise the %q prefix segment.
		e.User, e.App, e.Host, e.Port = "", "", "", 0
		e.Message = fmt.Sprintf(
			"automatic vacuum of table \"%s.public.%s\": index scans: 1\n\tpages: 0 removed, %d remain\n\ttuples: %d removed, %d remain",
			e.Database, table, r.IntN(100000), r.IntN(50000), r.IntN(1000000))

	case kindCheckpoint:
		e.Backend = "checkpointer"
		e.User, e.Database, e.App, e.Host, e.Port = "", "", "", "", 0
		if r.IntN(2) == 0 {
			e.Message = "checkpoint starting: time"
		} else {
			e.Message = fmt.Sprintf(
				"checkpoint complete: wrote %d buffers (%.1f%%); 0 WAL file(s) added, 0 removed, %d recycled; write=%.3f s, sync=%.3f s, total=%.3f s",
				r.IntN(20000), r.Float64()*20, r.IntN(30),
				r.Float64()*30, r.Float64(), r.Float64()*31)
		}

	case kindTempFile:
		e.Message = fmt.Sprintf(`temporary file: path "base/pgsql_tmp/pgsql_tmp%d.%d", size %d`,
			pid, r.IntN(20), (r.IntN(500)+1)*1024*1024)
		e.Statement = fmt.Sprintf("SELECT * FROM %s ORDER BY total", table)

	case kindLockWait:
		e.Message = fmt.Sprintf(
			"process %d still waiting for ShareLock on transaction %d after %d.%03d ms",
			pid, r.IntN(1000000), r.IntN(5000)+1000, r.IntN(1000))
		e.Detail = fmt.Sprintf("Process holding the lock: %d. Wait queue: %d.",
			r.IntN(30000), r.IntN(30000))
		e.Statement = fmt.Sprintf("UPDATE %s SET total = total + 1 WHERE id = %d", table, r.IntN(1000))

	case kindDeadlock:
		e.Severity = "ERROR"
		e.SQLState = "40P01"
		e.Message = "deadlock detected"
		e.Detail = fmt.Sprintf(
			"Process %d waits for ShareLock on transaction %d; blocked by process %d.",
			pid, r.IntN(1000000), r.IntN(30000))
		e.Hint = "See server log for query details."
		e.Statement = fmt.Sprintf("UPDATE %s SET total = 0 WHERE id = %d", table, r.IntN(1000))
	}

	e.TXID = int64(r.IntN(2000000))
	return e
}

// SeverityHistogram counts events by severity, which the manifest records so a
// corpus can be checked without being re-read (TST-003).
func SeverityHistogram(events []Event) map[string]int64 {
	h := make(map[string]int64)
	for i := range events {
		h[events[i].Severity]++
	}
	return h
}

// Written reports how many bytes a writer produced, for the manifest.
type Written struct {
	Bytes   int64
	Records int
}

// countingWriter tracks output size without buffering it.
type countingWriter struct {
	w io.Writer
	n int64
}

func (c *countingWriter) Write(p []byte) (int, error) {
	n, err := c.w.Write(p)
	c.n += int64(n)
	return n, err
}

// escapeCSV quotes a csvlog field, doubling any embedded quote.
func escapeCSV(sb *strings.Builder, s string) {
	sb.WriteByte('"')
	for i := range len(s) {
		if s[i] == '"' {
			sb.WriteByte('"')
		}
		sb.WriteByte(s[i])
	}
	sb.WriteByte('"')
}
